// resolved concrete URI in req.Params.URI; parse parameters from it yourself.
func ResourceTemplate(server *mcp.Server, uriTemplate string, name string, description string, mimeType string, handler ResourceHandler) {
	server.AddResourceTemplate(&mcp.ResourceTemplate{URITemplate: uriTemplate, Name: name, Description: description, MIMEType: mimeType}, handler)
}

// TextResourceTemplate registers a parameterized plain-text resource template.
// fn receives the concrete URI the client requested.
func TextResourceTemplate(server *mcp.Server, uriTemplate string, name string, description string, fn TextResourceFunc) {
	ResourceTemplate(server, uriTemplate, name, description, "text/plain", func(ctx context.Context, req *mcp.ReadResourceRequest) (*mcp.ReadResourceResult, error) {
		text, err := fn(req.Params.URI)
		if err != nil {
			return nil, err
		}
		return &mcp.ReadResourceResult{Contents: []*mcp.ResourceContents{&mcp.ResourceContents{URI: req.Params.URI, MIMEType: "text/plain", Text: text}}}, nil
	})
}

// PromptArg describes one argument of a Prompt.
type PromptArg struct {
	Name        string
	Description string
	Required    bool
}

// PromptHandler is the go-sdk handler type for prompt requests.
// The handler receives the prompt name and argument values in req.Params.
type PromptHandler = mcp.PromptHandler

// UserPromptFunc returns the text of a single user prompt message given the
// argument values supplied by the client.
type UserPromptFunc func(PromptArgs) (string, error)

// Prompt registers an MCP prompt with the given handler.
// Example:
//
//	mcp.Prompt(server, "summarize", "Summarize text",
//	    list of mcp.PromptArg{{Name: "text", Required: true}}, handler)
func Prompt(server *mcp.Server, name string, description string, args []PromptArg, handler PromptHandler) {
	promptArgs := make([]*mcp.PromptArgument, len(args))
	for i, a := range args {
		promptArgs[i] = &mcp.PromptArgument{Name: a.Name, Description: a.Description, Required: a.Required}
	}
	server.AddPrompt(&mcp.Prompt{Name: name, Description: description, Arguments: promptArgs}, handler)
}

// UserPrompt registers a prompt that returns a single user message containing
// the text returned by fn. fn receives the prompt's argument values keyed by
// argument name.
// Example:
//
//	mcp.UserPrompt(server, "summarize", "Summarize text",
//	    list of mcp.PromptArg{{Name: "text", Required: true}},
//	    (args) => "Summarize: " + args["text"], empty)
func UserPrompt(server *mcp.Server, name string, description string, args []PromptArg, fn UserPromptFunc) {
	Prompt(server, name, description, args, func(ctx context.Context, req *mcp.GetPromptRequest) (*mcp.GetPromptResult, error) {
		text, err := fn(req.Params.Arguments)
		if err != nil {
			return nil, err
		}
		return &mcp.GetPromptResult{Description: description, Messages: []*mcp.PromptMessage{&mcp.PromptMessage{Role: "user", Content: encodeContent(content.Text{Body: text})}}}, nil
	})
}

// ToolOpts customizes optional metadata when registering a tool.
// ReadOnly/Destructive/Idempotent/OpenWorldHint map to MCP tool annotation hints
// the client uses to decide auto-approval policy. Title is a human-readable
// display name shown in UIs (distinct from the machine-readable Name). Set
// OpenWorldHint=true for tools that reach external services (web search, APIs).
// OutputSchema (when non-nil) declares a structured output schema. All fields
// are optional — the zero value matches plain Tool() behavior.
type ToolOpts struct {
	ReadOnly      bool
	Destructive   bool
	Idempotent    bool
	OpenWorldHint bool
	Title         string
	OutputSchema  any
}

// ToolWithOpts is like Tool but accepts annotation hints and an output schema.
// Annotation hints are only emitted when set to true; leave them false to
// omit the hint entirely. T is the args struct the JSON arguments decode into;
// R is the handler's typed return value. Bind both at the call site with
// `of T and R` (use `of JSONObject and any` for the untyped form).
func ToolWithOpts[T any, R any](server *mcp.Server, name string, description string, schema any, opts ToolOpts, handler func(T) (R, error)) {
	err_10 := validateToolSchema(name, schema, handler)
	if err_10 != nil {
		panic(fmt.Sprintf("%v", err_10))
	}
	tool := &mcp.Tool{Name: name, Description: description, InputSchema: schema, OutputSchema: opts.OutputSchema}
	if opts.ReadOnly || opts.Destructive || opts.Idempotent || opts.OpenWorldHint || opts.Title != "" {
		a := &mcp.ToolAnnotations{}
		if opts.ReadOnly {
			a.ReadOnlyHint = true
		}
		if opts.Destructive {
			v := true
			a.DestructiveHint = &v
		}
		if opts.Idempotent {
			a.IdempotentHint = true
		}
		if opts.OpenWorldHint {
			v := true
			a.OpenWorldHint = &v
		}
		if opts.Title != "" {
			a.Title = opts.Title
		}
		tool.Annotations = a
	}
	server.AddTool(tool, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var args T
		if req.Params.Arguments != nil {
			unmarshalErr := json.ParseBytesInto(req.Params.Arguments, &args)
			if unmarshalErr != nil {
				return nil, unmarshalErr
			}
		}
		res, handlerErr := handler(args)
		if handlerErr != nil {
			return errorCallResult(handlerErr.Error()), nil
		}
		built, buildErr := buildCallResult(res)
		if buildErr != nil {
			return nil, buildErr
		}
		return built, nil
	})
}

// ToolContext is passed to ToolRich handlers and exposes runtime capabilities
// back to the connected client: progress reporting and elicitation.
type ToolContext struct {
	inner         *mcp.ServerSession
	progressToken any
}

// Progress sends a progress update to the client. The progress token is
// inherited from the originating tool call request; if the client did not
// supply a progress token the call is a no-op (returns nil without sending).
func (tc *ToolContext) Progress(ctx context.Context, progress float64, total float64, msg string) error {
	if tc.progressToken == nil {
		return nil
	}
	return tc.inner.NotifyProgress(ctx, &mcp.ProgressNotificationParams{ProgressToken: tc.progressToken, Progress: progress, Total: total, Message: msg})
}

// Elicit asks the connected client for structured input. Returns the action
// taken (ElicitAction.Accept | .Decline | .Cancel) and the user-supplied content
// (only valid when action equals ElicitAction.Accept). schema is the JSON schema
// describing the expected response shape.
func (tc *ToolContext) Elicit(ctx context.Context, message string, schema any) (ElicitAction, JSONObject, error) {
	result, err := tc.inner.Elicit(ctx, &mcp.ElicitParams{Message: message, RequestedSchema: schema})
	if err != nil {
		return ElicitAction(""), nil, err
	}
	return ElicitAction(result.Action), result.Content, nil
}

// ToolWithContextHandler is a tool handler that receives a ToolContext, giving it
// access to progress reporting and elicitation. Use with ToolWithContext.
// For typed-args handlers, inline the func signature and bind T and R with
// `mcp.ToolWithContext of MyArgs and MyResult(...)`.
type ToolWithContextHandler func(context.Context, *ToolContext, JSONObject) (any, error)

// ToolRichHandler is a tool handler that receives a ToolContext.
type ToolRichHandler = ToolWithContextHandler

// ToolWithContext registers an MCP tool whose handler receives a ToolContext.
// Use this when the tool needs to log, report progress, request user input,
// or query the client (instead of just returning a value). T is the args
// struct the JSON arguments decode into; R is the handler's typed return value.
// Bind both at the call site with `of T and R` (use `of JSONObject and any`
// for the untyped form). Pipe-friendly: server |> ToolWithContext of T and R(...)
func ToolWithContext[T any, R any](server *mcp.Server, name string, description string, schema any, handler func(context.Context, *ToolContext, T) (R, error)) {
	err_11 := validateToolSchema(name, schema, handler)
	if err_11 != nil {
		panic(fmt.Sprintf("%v", err_11))
	}
	server.AddTool(&mcp.Tool{Name: name, Description: description, InputSchema: schema}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var args T
		if req.Params.Arguments != nil {
			unmarshalErr := json.ParseBytesInto(req.Params.Arguments, &args)
			if unmarshalErr != nil {
				return nil, unmarshalErr
			}
		}
		tc := &ToolContext{inner: req.Session, progressToken: req.Params.GetProgressToken()}
		res, handlerErr := handler(ctx, tc, args)
		if handlerErr != nil {
			return errorCallResult(handlerErr.Error()), nil
		}
		built, buildErr := buildCallResult(res)
		if buildErr != nil {
			return nil, buildErr
		}
		return built, nil
	})
}

// ToolRich registers an MCP tool whose handler receives a ToolContext.
func ToolRich[T any, R any](server *mcp.Server, name string, description string, schema any, handler func(context.Context, *ToolContext, T) (R, error)) {
	err_12 := validateToolSchema(name, schema, handler)
	if err_12 != nil {
		panic(fmt.Sprintf("%v", err_12))
	}
	server.AddTool(&mcp.Tool{Name: name, Description: description, InputSchema: schema}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var args T
		if req.Params.Arguments != nil {
			unmarshalErr := json.ParseBytesInto(req.Params.Arguments, &args)
			if unmarshalErr != nil {
				return nil, unmarshalErr
			}
		}
		tc := &ToolContext{inner: req.Session, progressToken: req.Params.GetProgressToken()}
		res, handlerErr := handler(ctx, tc, args)
		if handlerErr != nil {
			return errorCallResult(handlerErr.Error()), nil
		}
		built, buildErr := buildCallResult(res)
		if buildErr != nil {
			return nil, buildErr
		}
		return built, nil
	})
}

// HTTPOptions configures the streamable HTTP server transport.
// Set Stateless to true to speak protocol version 2026-07-28: each request
// is self-contained (no Mcp-Session-Id, no server->client callbacks) and the
// server ignores DELETE / GET standalone streams. Stateless is the
// sessionless direction of the MCP spec (SEP-2567); use it for new HTTP
// deployments. Leave it false to keep stateful sessions and the legacy
// initialize handshake, which server->client calls (Elicit / Progress /
// ToolRich) require.
type HTTPOptions struct {
	Stateless bool
}

// ServeHTTP runs the server over a streamable HTTP transport at the given
// address (blocking), stateless by default so it speaks protocol version
// 2026-07-28. Pass opts.Stateless = false to keep stateful sessions (the
// legacy 2025-11-25 wire form, required when tools use server->client
// callbacks like Elicit / Progress / CreateMessage). BEWARE: no
// authentication, no TLS — any client that
// can reach the port can invoke every registered tool. For production
// deployments wrap the handler with your own middleware/TLS, or use the
// http.Handler directly via the mcp.NewStreamableHTTPHandler pattern.
// Example: server |> mcp.ServeHTTP(":8080") onerr panic "{error}"
// Example (stateful): server |> mcp.ServeHTTP(":8080", {Stateless: false}) onerr panic "{error}"
func ServeHTTP(server *mcp.Server, addr string, opts *HTTPOptions) error {
	o := mcp.StreamableHTTPOptions{}
	if opts != nil {
		o.Stateless = opts.Stateless
	} else {
		o.Stateless = true
	}
	handler := mcp.NewStreamableHTTPHandler(func(req *http.Request) *mcp.Server { return server }, &o)
	return httppkg.Serve(addr, handler)
}

// ClientResource describes an MCP resource discovered from a server.
type ClientResource struct {
	URI         string
	Name        string
	Description string
	MIMEType    string
}

// ClientResourceTemplate describes an MCP resource template.
type ClientResourceTemplate struct {
	URITemplate string
	Name        string
	Description string
	MIMEType    string
}

// ClientPrompt describes an MCP prompt discovered from a server.
type ClientPrompt struct {
	Name        string
	Description string
	Arguments   []PromptArg
}

// ListResources retrieves the available resources from the connected server.
func ListResources(ctx context.Context, session *ClientSession) ([]ClientResource, error) {
	result, err_13 := session.inner.ListResources(ctx, nil)
	if err_13 != nil {
		err_13 = fmt.Errorf("MCP ListResources failed: %w", err_13)
		return []ClientResource{}, err_13
	}
	out := make([]ClientResource, len(result.Resources))
	for i, r := range result.Resources {
		out[i] = ClientResource{URI: r.URI, Name: r.Name, Description: r.Description, MIMEType: r.MIMEType}
	}
	return out, nil
}

// ListResourceTemplates retrieves the resource templates from the server.
func ListResourceTemplates(ctx context.Context, session *ClientSession) ([]ClientResourceTemplate, error) {
	result, err_14 := session.inner.ListResourceTemplates(ctx, nil)
	if err_14 != nil {
		err_14 = fmt.Errorf("MCP ListResourceTemplates failed: %w", err_14)
		return []ClientResourceTemplate{}, err_14
	}
	out := make([]ClientResourceTemplate, len(result.ResourceTemplates))
	for i, r := range result.ResourceTemplates {
		out[i] = ClientResourceTemplate{URITemplate: r.URITemplate, Name: r.Name, Description: r.Description, MIMEType: r.MIMEType}
	}
	return out, nil
}

// ReadResource reads a resource by URI and returns its contents.
// A single resource may have multiple content entries (rare for text, more
// common for embedded multi-file resources).
func ReadResource(ctx context.Context, session *ClientSession, uri string) ([]*mcp.ResourceContents, error) {
	result, err_15 := session.inner.ReadResource(ctx, &mcp.ReadResourceParams{URI: uri})
	if err_15 != nil {
		return []*mcp.ResourceContents{}, fmt.Errorf("MCP ReadResource \"%v\" failed: %v", uri, err_15)
	}
	return result.Contents, nil
}

// ListPrompts retrieves the available prompts from the connected server.
func ListPrompts(ctx context.Context, session *ClientSession) ([]ClientPrompt, error) {
	result, err_16 := session.inner.ListPrompts(ctx, nil)
	if err_16 != nil {
		err_16 = fmt.Errorf("MCP ListPrompts failed: %w", err_16)
		return []ClientPrompt{}, err_16
	}
	out := make([]ClientPrompt, len(result.Prompts))
	for i, p := range result.Prompts {
		args := make([]PromptArg, len(p.Arguments))
		for j, a := range p.Arguments {
			args[j] = PromptArg{Name: a.Name, Description: a.Description, Required: a.Required}
		}
		out[i] = ClientPrompt{Name: p.Name, Description: p.Description, Arguments: args}
	}
	return out, nil
}

// GetPrompt retrieves a prompt by name with the given arguments.
func GetPrompt(ctx context.Context, session *ClientSession, name string, args PromptArgs) (*mcp.GetPromptResult, error) {
	return session.inner.GetPrompt(ctx, &mcp.GetPromptParams{Name: name, Arguments: args})
}

// CompletionHandler is a server-level handler for completion/complete requests.
// It receives the reference (prompt name or resource URI), the argument being
// completed, and its partial value, then returns candidate values.
// Build one with CompletionRouter.Handler() or implement it directly.
type CompletionHandler func(context.Context, *mcp.CompleteRequest) (*mcp.CompleteResult, error)

// NewWithCompletion creates an MCP server pre-wired with a completion handler.
// Pass router.Handler() for per-prompt and per-resource completion, or supply
// a custom handler for full control.
// Example:
//
//	router := mcp.NewRouter()
//	router |> mcp.AddPrompt("summarize", completer)
//	server := mcp.NewWithCompletion("my-server", "1.0.0", router |> mcp.Handler())
func NewWithCompletion(name string, version string, handler CompletionHandler) *mcp.Server {
	opts := &mcp.ServerOptions{CompletionHandler: handler}
	return mcp.NewServer(&mcp.Implementation{Name: name, Version: version}, opts)
}

// Completions builds a CompleteResult with the given suggested values.
// This is the typical return value from a CompletionHandler or PromptCompleter.
// Example:
//
//	return mcp.Completions(list of string{"alice", "bob", "carol"}), empty
func Completions(values []string) *mcp.CompleteResult {
	return &mcp.CompleteResult{Completion: mcp.CompletionResultDetails{Values: values}}
}

// CompletionsPage builds a paginated CompleteResult. Set hasMore = true when
// there are more values beyond this page; total is the full count (0 = unknown).
func CompletionsPage(values []string, hasMore bool, total int) *mcp.CompleteResult {
	return &mcp.CompleteResult{Completion: mcp.CompletionResultDetails{Values: values, HasMore: hasMore, Total: total}}
}

// PromptCompleter returns completion candidates for one argument of a prompt.
// argName is the argument being completed, partial is what the user has typed,
// and ctx holds previously-resolved argument values.
type PromptCompleter func(string, string, PromptArgs) []string

// ResourceCompleter returns completion candidates for a resource URI template
// variable. Arguments are: argName, partial value, previously-resolved vars.
type ResourceCompleter func(string, string, PromptArgs) []string

// CompletionRouter dispatches completion/complete requests to per-prompt and
// per-resource completers registered by name. Build one with NewRouter() and
// pass its Handler() method to NewWithCompletion.
type CompletionRouter struct {
	prompts   map[string]PromptCompleter
	resources map[string]ResourceCompleter
}

// NewRouter creates a new empty CompletionRouter.
func NewRouter() *CompletionRouter {
	return &CompletionRouter{prompts: map[string]PromptCompleter{}, resources: map[string]ResourceCompleter{}}
}

// AddPrompt registers a PromptCompleter for the named prompt.
// Chainable for pipe builder: router |> .AddPrompt("p", fn) |> .AddResource("r", fn)
func (r *CompletionRouter) AddPrompt(promptName string, completer PromptCompleter) *CompletionRouter {
	r.prompts[promptName] = completer
	return r
}

// AddResource registers a ResourceCompleter for the given resource URI (or URI
// template). The URI must match exactly the URI/template used in Resource() or
// ResourceTemplate(). Chainable for pipe builder.
func (r *CompletionRouter) AddResource(resourceURI string, completer ResourceCompleter) *CompletionRouter {
	r.resources[resourceURI] = completer
	return r
}

// Handler returns the CompletionHandler for this router, ready to pass to
// NewWithCompletion. Dispatches by ref type (ref/prompt or ref/resource),
// then by prompt name or resource URI. Returns an empty completion list when no
// completer is registered for the reference.
func (r *CompletionRouter) Handler() CompletionHandler {
	return func(ctx context.Context, req *mcp.CompleteRequest) (*mcp.CompleteResult, error) {
		if req.Params.Ref == nil {
			return Completions([]string{}), nil
		}
		argName := req.Params.Argument.Name
		partial := req.Params.Argument.Value
		prevArgs := *new(PromptArgs)
		if req.Params.Context != nil {
			prevArgs = req.Params.Context.Arguments
		}
		switch req.Params.Ref.Type {
		case "ref/prompt":
			pc, ok1 := r.prompts[req.Params.Ref.Name]
			if ok1 {
				return Completions(pc(argName, partial, prevArgs)), nil
			}
		case "ref/resource":
			rc, ok2 := r.resources[req.Params.Ref.URI]
			if ok2 {
				return Completions(rc(argName, partial, prevArgs)), nil
			}
		}
		return Completions([]string{}), nil
	}
}

// Server is the MCP server type. Returned by New(); pass it to Tool() and Serve().
type Server = mcp.Server

// ReadResourceRequest is the server-side request received by a ResourceHandler.
// Use req.Params.URI to read the concrete URI requested by the client.
type ReadResourceRequest = mcp.ReadResourceRequest

// ReadResourceResult is the value a ResourceHandler returns. Contents holds
// one or more *ResourceContents (typically a single Text or Blob entry).
type ReadResourceResult = mcp.ReadResourceResult

// GetPromptRequest is the server-side request received by a PromptHandler.
// Use req.Params.Arguments to access the prompt arguments.
type GetPromptRequest = mcp.GetPromptRequest

// GetPromptResult is the value a PromptHandler returns. Messages holds the
// conversation turns the client should seed the prompt with.
type GetPromptResult = mcp.GetPromptResult

// PromptMessage is a single conversation turn returned from a prompt.
type PromptMessage = mcp.PromptMessage

// CompleteRequest is the server-side completion request.
// Inspect req.Params.Ref.Type ("ref/prompt" or "ref/resource"),
// req.Params.Ref.Name/URI, req.Params.Argument.Name, and
// req.Params.Argument.Value in your CompletionHandler.
type CompleteRequest = mcp.CompleteRequest

// CompleteResult is the value your CompletionHandler returns.
// Use Completions() or CompletionsPage() to build one.
type CompleteResult = mcp.CompleteResult
